const courses = ["HTML", "CSS", "Python"];
export default function CourseList() {
  return <ul>{courses.map(course => <li key={course}>{course}</li>)}</ul>;
}

const lessons = [{ id: 1, title: "Tags" }, { id: 2, title: "Links" }];
export default function Lessons() {
  return <ul>{lessons.map(lesson => <li key={lesson.id}>{lesson.title}</li>)}</ul>;
}

export default function LoadingState({ loading, items }) {
  if (loading) return <p>Loading courses…</p>;
  if (items.length === 0) return <p>No courses found.</p>;
  return <p>{items.length} courses available.</p>;
}

const completed = new Set([1, 3]);
export default function Checklist() {
  return <ul>{[1,2,3].map(id => <li key={id}>{completed.has(id) ? "Done" : "Pending"} — Lesson {id}</li>)}</ul>;
}
